#!/usr/bin/env python
import contextlib as __stickytape_contextlib

@__stickytape_contextlib.contextmanager
def __stickytape_temporary_dir():
    import tempfile
    import shutil
    dir_path = tempfile.mkdtemp()
    try:
        yield dir_path
    finally:
        shutil.rmtree(dir_path)

with __stickytape_temporary_dir() as __stickytape_working_dir:
    def __stickytape_write_module(path, contents):
        import os, os.path

        def make_package(path):
            parts = path.split("/")
            partial_path = __stickytape_working_dir
            for part in parts:
                partial_path = os.path.join(partial_path, part)
                if not os.path.exists(partial_path):
                    os.mkdir(partial_path)
                    with open(os.path.join(partial_path, "__init__.py"), "wb") as f:
                        f.write(b"\n")

        make_package(os.path.dirname(path))

        full_path = os.path.join(__stickytape_working_dir, path)
        with open(full_path, "wb") as module_file:
            module_file.write(contents)

    import sys as __stickytape_sys
    __stickytape_sys.path.insert(0, __stickytape_working_dir)

    __stickytape_write_module('action.py', b'"""Building blocks for converting the bash setup scripts into readable, re-runnable steps.\n\nAn Action is one unit of change with three phases:\n\n    precheck()   True if the desired state already holds (run is skipped)\n    run()        make the change\n    postcheck()  True if the desired state now holds (False aborts)\n\nLike `set -e`, a failure stops the runner unless the action opts in via continue_on_error\n(the equivalent of a bash `|| true`).\n"""\n\nfrom __future__ import annotations\n\nimport enum\nimport logging\nfrom abc import ABC, abstractmethod\nfrom dataclasses import dataclass\nfrom typing import Iterable\n\nlog = logging.getLogger(__name__)\n\n\nclass Status(enum.Enum):\n    SKIPPED = "skipped"  # precheck passed, nothing to do\n    CHANGED = "changed"  # run executed and postcheck passed\n    UNVERIFIED = "unverified"  # run executed, but the action defines no postcheck\n    FAILED = "failed"    # only seen for continue_on_error actions\n\n\nclass ActionError(RuntimeError):\n    """An action failed in run() or its postcheck()."""\n\n    def __init__(self, action: "Action", message: str):\n        super().__init__(f"{action.name}: {message}")\n        self.action = action\n\n\n@dataclass(frozen=True)\nclass Result:\n    action: "Action"\n    status: Status\n    error: BaseException | None = None\n\n\nclass Action(ABC):\n    #: Set True for steps that mirror a bash `|| true`: a failure is logged, not raised.\n    continue_on_error: bool = False\n    #: Label shown in log lines; set by whoever assembles the action list.\n    section: str = ""\n    #: A precheck() that returns False may set this to say what is off; it is logged and shown by --check.\n    precheck_detail: str = ""\n    #: A postcheck() that returns False may set this to say why; it is appended to the failure message.\n    postcheck_detail: str = ""\n\n    def __init__(self, name: str):\n        self.name = name\n\n    @abstractmethod\n    def precheck(self) -> bool:\n        """Return True when the desired state already holds, so run() is skipped."""\n\n    @abstractmethod\n    def run(self) -> None:\n        """Apply the change. Raise on failure."""\n\n    @abstractmethod\n    def postcheck(self) -> bool:\n        """Return True when the desired state holds after run()."""\n\n    def verifiable(self) -> bool:\n        """False when this action has nothing to check after run(); it then ends UNVERIFIED, not CHANGED."""\n        return True\n\n    def _log(self, phase: str, message: str = "", level: int = logging.INFO) -> None:\n        tag = f"[{self.section or \'-\'}][{phase}]"\n        log.log(level, "%-22s %s%s", tag, self.name, f" -> {message}" if message else "")\n\n    def execute(self) -> Result:\n        """Run the precheck -> run -> postcheck sequence for this action."""\n        phase = "Precheck"\n        try:\n            satisfied = self.precheck()\n            if satisfied:\n                self._log("Precheck", "satisfied, skipping")\n                return Result(\n                    action=self,\n                    status=Status.SKIPPED,\n                )\n            self._log("Precheck", f"not satisfied: {self.precheck_detail}" if self.precheck_detail else "not satisfied")\n            phase = "Run"\n            self._log("Run")\n            self.run()\n            if not self.verifiable():\n                self._log("Postcheck", "skipped (no check defined)")\n                return Result(\n                    action=self,\n                    status=Status.UNVERIFIED,\n                )\n            phase = "Postcheck"\n            if not self.postcheck():\n                raise ActionError(\n                    action=self,\n                    message="postcheck failed after run"\n                    + (f": {self.postcheck_detail}" if self.postcheck_detail else ""),\n                )\n            self._log("Postcheck", "ok")\n        except Exception as exc:\n            if self.continue_on_error:\n                self._log(phase, f"FAILED (ignored): {exc}", logging.WARNING)\n                return Result(\n                    action=self,\n                    status=Status.FAILED,\n                    error=exc,\n                )\n            self._log(phase, f"FAILED: {exc}", logging.ERROR)\n            if isinstance(exc, ActionError):\n                raise\n            raise ActionError(\n                action=self,\n                message=str(exc),\n            ) from exc\n        return Result(\n            action=self,\n            status=Status.CHANGED,\n        )\n\n    def __repr__(self) -> str:\n        return f"{type(self).__name__}({self.name!r})"\n\n\ndef run_actions(actions: Iterable[Action]) -> list[Result]:\n    """Execute actions in order, stopping at the first non-ignorable failure. Logs a summary at the end."""\n    results: list[Result] = []\n    try:\n        for action in actions:\n            results.append(action.execute())\n    finally:\n        counts = {s: sum(r.status is s for r in results) for s in Status}\n        log.info("Summary: %d changed, %d unverified, %d skipped, %d failed (ignored)",\n                 counts[Status.CHANGED], counts[Status.UNVERIFIED], counts[Status.SKIPPED], counts[Status.FAILED])\n    return results\n')
    __stickytape_write_module('config.py', b'"""All settings of alma-setup in one place (the variable block of the bash script).\n\nRun-time overrides come from the environment (put them AFTER sudo, which resets it):\n    sudo SYSTEM_HOSTNAME=foo STATIC_IP=192.168.1.50/24 STATIC_GATEWAY=192.168.1.1 python3 alma-setup/main.py\nEverything else is plain configuration: edit it in place.\n"""\n\nfrom __future__ import annotations\n\nimport os\nfrom dataclasses import dataclass\n\nMIDFIX = "from-setup"\n\n\n@dataclass(frozen=True)\nclass Config:\n    # --- run-time overrides (see from_env) ---\n    hostname: str = ""        # short name; used for the /etc/hosts alias and to derive fqdn\n    domain: str = ""\n    fqdn: str = ""            # derived as <lowercased hostname>.<domain> when both are set\n    static_ip: str = ""       # IPv4 CIDR; empty keeps the current network config\n    static_gateway: str = ""  # empty = gateway of the current default route\n    static_dns: str = ""      # space-separated\n    static_iface: str = ""    # empty = interface of the current default route\n    admin_pubkey: str = ""    # filled in by preflight\n    keymap: str = "jp106"     # console keymap (Japanese JIS); empty keeps the current one\n    sudo_user: str = ""       # never pruned\n\n    # --- accounts ---\n    admin_user: str = "devola"\n    service_user: str = "popola"\n    admin_group: str = "wheel"\n    admin_shell: str = "/bin/bash"\n    service_shell: str = "/usr/sbin/nologin"\n    service_comment: str = "Service Account"\n    # Pre-hashed passwords. Generate with: openssl passwd -6 \'your_password_here\'\n    root_password_hash: str = "$6$N2iKTCTMzAmc51w4$Ohp2YKKOQbHmGezRtJSJYg1BdsirMy70L4mUjRg/o5M9xSj45UHf.2w.CHTcSmCh4c2KsrDxnEhoYj3RsQCb71" # intentional, password is high entropy.\n    admin_password_hash: str = "$6$TsJ5LrQMrfwVrUJi$pdbXq3DnZZ1e6PJy8ex.xesPUHmWzmuth5RhWlSrKzYKe1jsrvaWrIidZLOD7AwJZuVMNKAIbTuNlf85H4.oU." # intentional, password is high entropy.\n    admin_pubkey_url: str = "https://raw.githubusercontent.com/reverseon/ishiori-ssot/refs/heads/main/portable/files/ishiori-master-key.pub"\n\n    # --- sudo / su ---\n    sudo_log: str = "/var/log/sudo.log"\n    su_bin: str = "/usr/bin/su"\n    su_mode: int = 0o4750  # group-owned, setuid kept, other users get no execute\n\n    # --- ssh ---\n    ssh_port: int = 22\n\n    # --- network ---\n    nm_priority: int = 100  # above the stock profile (0) so this one wins\n    static_apply_delay: str = "5s"\n\n    # --- authselect ---\n    authselect_profile: str = "local"\n    authselect_features: tuple[str, ...] = ("without-nullok", "with-faillock")\n\n    packages: tuple[str, ...] = (\n        "curl", "wget", "git", "vim-enhanced", "htop", "tmux", "gcc", "make", "python3", "python3-pip",\n        "qemu-guest-agent", "nftables", "dnf-automatic", "dnf-plugins-core", "audit", "audit-rules",\n        "chrony", "cronie", "at", "rsyslog", "logrotate",\n    )\n\n    @classmethod\n    def from_env(cls, env: dict[str, str] | None = None) -> "Config":\n        env = os.environ if env is None else env\n        hostname, domain, fqdn = env.get("SYSTEM_HOSTNAME", ""), env.get("SYSTEM_DOMAIN", ""), env.get("SYSTEM_FQDN", "")\n        if not fqdn and hostname and domain:\n            fqdn = f"{hostname.lower()}.{domain}"\n        return cls(\n            hostname=hostname, domain=domain, fqdn=fqdn, keymap=env.get("KEYMAP", "jp106"),\n            sudo_user=env.get("SUDO_USER", ""),\n            static_ip=env.get("STATIC_IP", ""), static_gateway=env.get("STATIC_GATEWAY", ""),\n            static_dns=env.get("STATIC_DNS", ""), static_iface=env.get("STATIC_IFACE", ""),\n        )\n\n    # --- derived: hostname ---\n    @property\n    def static_hostname(self) -> str:\n        """The FQDN if there is one (RHEL convention), else the short name."""\n        return self.fqdn or self.hostname\n\n    @property\n    def hosts_file(self) -> str:\n        return "/etc/hosts"\n\n    @property\n    def hosts_marker(self) -> str:\n        return f"# {MIDFIX}-hostname"\n\n    @property\n    def hosts_line(self) -> str:\n        return f"127.0.1.1 {\' \'.join(f\'{self.fqdn} {self.hostname}\'.split())} {self.hosts_marker}"\n\n    # --- derived: paths (all named after MIDFIX so they are recognisably ours) ---\n    @property\n    def nm_conf(self) -> str:\n        return f"/etc/NetworkManager/system-connections/{MIDFIX}-static.nmconnection"\n\n    @property\n    def nm_connection(self) -> str:\n        return f"{MIDFIX}-static"\n\n    @property\n    def ssh_conf(self) -> str:\n        # 00- prefix: sshd keeps the first value per option, so this must sort before the other drop-ins\n        return f"/etc/ssh/sshd_config.d/00-{MIDFIX}-ssh.conf"\n\n    @property\n    def ssh_banner(self) -> str:\n        return f"/etc/ssh/banner-{MIDFIX}.net"\n\n    @property\n    def admin_ssh_dir(self) -> str:\n        return f"/home/{self.admin_user}/.ssh"\n\n    @property\n    def admin_authorized_keys(self) -> str:\n        return f"{self.admin_ssh_dir}/authorized_keys"\n\n    @property\n    def sudoers_dir(self) -> str:\n        return "/etc/sudoers.d"\n\n    @property\n    def sudo_conf(self) -> str:\n        return f"{self.sudoers_dir}/99-{MIDFIX}-sudo"\n\n    @property\n    def admin_sudoers_conf(self) -> str:\n        return f"{self.sudoers_dir}/99-{MIDFIX}-{self.admin_user}"\n\n    @property\n    def service_sudoers_conf(self) -> str:\n        return f"{self.sudoers_dir}/99-{MIDFIX}-{self.service_user}"\n\n    # su guard\n    @property\n    def su_guard_bin(self) -> str:\n        return f"/usr/local/sbin/{MIDFIX}-su-guard"\n\n    @property\n    def su_guard_service(self) -> str:\n        return f"{MIDFIX}-su-guard.service"\n\n    @property\n    def su_guard_path(self) -> str:\n        return f"{MIDFIX}-su-guard.path"\n\n    @property\n    def su_guard_timer(self) -> str:\n        return f"{MIDFIX}-su-guard.timer"\n\n    # reboot-check\n    dnf_dropin_dir: str = "/etc/systemd/system/dnf-automatic.service.d"\n\n    @property\n    def reboot_notice_file(self) -> str:\n        return f"/run/motd.d/50-{MIDFIX}-reboot-required"\n\n    @property\n    def reboot_check_bin(self) -> str:\n        return f"/usr/local/sbin/{MIDFIX}-reboot-check"\n\n    @property\n    def nft_rules_conf(self) -> str:\n        return f"/etc/nftables/{MIDFIX}-inet-filter.nft"\n\n    @property\n    def nft_include(self) -> str:\n        return f\'include "{self.nft_rules_conf}"\'\n')
    __stickytape_write_module('sections/__init__.py', b'')
    __stickytape_write_module('sections/firewall.py', b'"""nftables as the only firewall manager."""\n\nimport texts\nfrom actions import EnsureDir, EnsureLine, Systemctl, WriteFile\nfrom config import Config\n\n\ndef actions(c: Config):\n    return [\n        EnsureDir(\n            path="/etc/nftables",\n        ),\n        WriteFile(\n            path=c.nft_rules_conf,\n            text=texts.nft_rules(c),\n        ),\n        # Include the ruleset in the main nftables config so it persists across reboots\n        EnsureLine(\n            path="/etc/sysconfig/nftables.conf",\n            line=c.nft_include,\n        ),\n        # Mask firewalld so it cannot load a second ruleset\n        Systemctl(\n            verb="disable_now",\n            units=["firewalld"],\n            continue_on_error=True,\n        ),\n        Systemctl(\n            verb="mask",\n            units=["firewalld"],\n            continue_on_error=True,\n        ),\n        Systemctl(\n            verb="enable",\n            units=["nftables"],\n        ),\n        Systemctl(\n            verb="restart",\n            units=["nftables"],\n        ),\n    ]\n')
    __stickytape_write_module('texts.py', b'"""File bodies written by alma-setup (the heredocs of the bash script).\n\nEvery body ends exactly as the bash heredoc did (a trailing newline), so the files are byte-identical.\nBodies full of shell `${...}` use @@NAME@@ placeholders (see `render`) instead of f-strings.\n"""\n\nfrom __future__ import annotations\n\nimport re\n\nimport art\nfrom config import MIDFIX, Config\n\n\ndef render(template: str, **values: object) -> str:\n    return re.sub(r"@@(\\w+)@@", lambda m: str(values[m.group(1)]), template)\n\n\ndef daily_timer(description: str) -> str:\n    return render("""\\\n[Unit]\nDescription=@@desc@@\n\n[Timer]\nOnCalendar=daily\nPersistent=true\n\n[Install]\nWantedBy=timers.target\n""", desc=description)\n\n\n# ---- sudo / su ----------------------------------------------------------------------------------\n\ndef sudo_conf(c: Config) -> str:\n    return f"""\\\nDefaults use_pty\nDefaults timestamp_timeout=15\nDefaults umask=0022\nDefaults umask_override\nDefaults log_host,logfile="{c.sudo_log}"\n"""\n\n\ndef admin_sudoers(c: Config) -> str:\n    return f"{c.admin_user} ALL=(ALL) ALL\\n"\n\n\ndef service_sudoers(c: Config) -> str:\n    # The admin may open a login shell as the service user without a password\n    return f"{c.admin_user} ALL=({c.service_user}) NOPASSWD: /bin/bash -l\\n"\n\n\ndef su_guard_bin(c: Config) -> str:\n    # Only writes on drift, otherwise its own chmod would retrigger the path unit in a loop\n    return f"""\\\n#!/bin/sh\nset -eu\n[ "$(stat -c \'%a %G\' "{c.su_bin}")" = "{c.su_mode:o} {c.admin_group}" ] && exit 0\nchgrp "{c.admin_group}" "{c.su_bin}"\nchmod "{c.su_mode:o}" "{c.su_bin}"\nlogger -t {MIDFIX}-su-guard "restored {c.su_bin} to {c.su_mode:o} {c.admin_group}"\n"""\n\n\ndef su_guard_service(c: Config) -> str:\n    return f"""\\\n[Unit]\nDescription=Re-apply restricted permissions on {c.su_bin}\n\n[Service]\nType=oneshot\nExecStart={c.su_guard_bin}\n"""\n\n\ndef su_guard_path(c: Config) -> str:\n    return f"""\\\n[Unit]\nDescription=Watch {c.su_bin} for permission resets\n\n[Path]\nPathChanged={c.su_bin}\nUnit={c.su_guard_service}\n\n[Install]\nWantedBy=multi-user.target\n"""\n\n\ndef su_guard_timer(c: Config) -> str:\n    # Fallback in case inotify misses the package manager replacing the file\n    return f"""\\\n[Unit]\nDescription=Periodically re-apply restricted permissions on {c.su_bin}\n\n[Timer]\nOnBootSec=2min\nOnUnitActiveSec=1h\nUnit={c.su_guard_service}\n\n[Install]\nWantedBy=timers.target\n"""\n\n\n# ---- login experience -----------------------------------------------------------------------------\n\ndef ssh_banner() -> str:\n    return art.BANNER + "\\n"  # bash: printf \'%s\\n\'\n\n\ndef motd(c: Config) -> str:\n    # Note under the art: the service user has no direct login\n    popola_note = f\'  - To switch to the {c.service_user} service user, run "sudo -u {c.service_user} /bin/bash -l".\\n\'\n    return f"{art.MOTD}\\n\\nNotes:\\n{popola_note}"\n\n\nFAILLOCK_CONF = """\\\ndeny = 5\nunlock_time = 900\n"""\n\n# Not readonly (override with TMOUT=0); skipped inside tmux/screen, where idle panes are expected\nTIMEOUT_CONF = """\\\nif [ -z "${TMUX:-}" ] && [ -z "${STY:-}" ]; then\n  export TMOUT=900\nfi\n"""\n\n# Not applied to root. The sudo config sets "umask=0022" + "umask_override" so files created\n# under sudo don\'t inherit 027 (sudo ORs the caller\'s umask) and stay readable by services\nUMASK_CONF = """\\\nif [ "$(id -u)" -ne 0 ]; then\n  umask 027\nfi\n"""\n\n\ndef ssh_conf(c: Config) -> str:\n    return f"""\\\nPort {c.ssh_port}\nPermitRootLogin no\nAllowUsers {c.admin_user}\nAuthenticationMethods publickey\nPubkeyAuthentication yes\nPubkeyAcceptedAlgorithms ssh-ed25519,sk-ssh-ed25519@openssh.com\nPasswordAuthentication no\nKbdInteractiveAuthentication no\nPermitEmptyPasswords no\nMaxAuthTries 3\nLoginGraceTime 30\nMaxSessions 4\nClientAliveInterval 300\nClientAliveCountMax 2\nX11Forwarding no\nAllowAgentForwarding no\nAllowTcpForwarding no\nBanner {c.ssh_banner}\n"""\n\n\ndef sshd_expected(c: Config) -> tuple[str, ...]:\n    """Effective `sshd -T` lines that must hold (an earlier drop-in could silently override ours)."""\n    return (\n        "permitrootlogin no", "passwordauthentication no", "kbdinteractiveauthentication no",\n        "permitemptypasswords no", "pubkeyauthentication yes", "authenticationmethods publickey",\n        f"allowusers {c.admin_user}", "pubkeyacceptedalgorithms ssh-ed25519,sk-ssh-ed25519@openssh.com",\n        "maxauthtries 3", "x11forwarding no", "allowagentforwarding no", "allowtcpforwarding no",\n    )\n\n\n# ---- updates, kernel, audit -------------------------------------------------------------------------\n\nDNF_AUTOMATIC_CONF = """\\\n[commands]\nupgrade_type = security\nrandom_sleep = 0\ndownload_updates = yes\napply_updates = yes\n\n[emitters]\nemit_via = stdio\n"""\n\nSYSCTL_HARDENING = """\\\nnet.ipv4.conf.all.rp_filter = 2\nnet.ipv4.conf.default.rp_filter = 2\nnet.ipv4.conf.all.accept_redirects = 0\nnet.ipv4.conf.default.accept_redirects = 0\nnet.ipv6.conf.all.accept_redirects = 0\nnet.ipv6.conf.default.accept_redirects = 0\nnet.ipv4.conf.all.send_redirects = 0\nnet.ipv4.conf.default.send_redirects = 0\nnet.ipv4.conf.all.accept_source_route = 0\nnet.ipv4.conf.default.accept_source_route = 0\nnet.ipv6.conf.all.accept_source_route = 0\nnet.ipv6.conf.default.accept_source_route = 0\nnet.ipv4.tcp_syncookies = 1\nnet.ipv4.icmp_echo_ignore_broadcasts = 1\nkernel.kptr_restrict = 2\nkernel.dmesg_restrict = 1\nkernel.yama.ptrace_scope = 1\nfs.protected_hardlinks = 1\nfs.protected_symlinks = 1\n"""\n\n# Auditing: identity, sudo and sshd config files, and the use of su/sudo\nAUDIT_RULES = """\\\n-w /etc/passwd -p wa -k identity\n-w /etc/shadow -p wa -k identity\n-w /etc/group -p wa -k identity\n-w /etc/gshadow -p wa -k identity\n-w /etc/sudoers -p wa -k sudoers\n-w /etc/sudoers.d/ -p wa -k sudoers\n-w /etc/ssh/ -p wa -k sshd_config\n-w /usr/bin/su -p x -k priv_cmd\n-w /usr/bin/sudo -p x -k priv_cmd\n"""\n\nLIMITS_NOCORE = "* hard core 0\\n"\nSYSCTL_NOCORE = "fs.suid_dumpable = 0\\n"\n\n# /tmp is left alone: on the stock layout it lives on the root filesystem and a noexec /tmp breaks dnf scriptlets\nSHM_DROPIN = """\\\n[Mount]\nOptions=mode=1777,nosuid,nodev,noexec\n"""\n\n\n# ---- logging ---------------------------------------------------------------------------------------\n\n# ---- firewall --------------------------------------------------------------------------------------\n\ndef nft_rules(c: Config) -> str:\n    return render("""\\\ntable inet filter {\n  chain input {\n    type filter hook input priority 0; policy drop;\n\n    # Accept loopback traffic\n    iif lo accept\n\n    # Drop invalid connection state packets\n    ct state invalid drop\n\n    # Accept established/related connections\n    ct state established,related accept\n\n    # Rate limit new SSH connections per source address (IPv4 and IPv6)\n    tcp dport @@port@@ ct state new meter ssh-v4 { ip saddr limit rate 5/second } accept\n    tcp dport @@port@@ ct state new meter ssh-v6 { ip6 saddr limit rate 5/second } accept\n\n    # Accept ICMP for diagnostics (IPv4)\n    icmp type echo-request accept\n\n    # Accept ICMPv6 needed for IPv6 to function (ND, path MTU discovery, MLD) and diagnostics\n    icmpv6 type { echo-request, destination-unreachable, packet-too-big, time-exceeded, parameter-problem, nd-neighbor-solicit, nd-neighbor-advert, nd-router-advert, nd-router-solicit, nd-redirect, mld-listener-query, mld-listener-report, mld2-listener-report } accept\n\n    # Accept DHCPv6 replies (no conntrack match when the request was multicast)\n    ip6 saddr fe80::/10 udp sport 547 udp dport 546 accept\n\n    # Accept DHCPv4 replies (broadcast offers/acks and rebinds don\'t match conntrack)\n    udp sport 67 udp dport 68 accept\n\n    # Log (rate limited) and drop everything else\n    limit rate 1/second log prefix "[nftables] DROP: " flags all\n  }\n\n  chain forward {\n    type filter hook forward priority 0; policy drop;\n  }\n\n  chain output {\n    type filter hook output priority 0; policy accept;\n  }\n}\n""", port=c.ssh_port)\n\n\n# ---- network ---------------------------------------------------------------------------------------\n\ndef nm_keyfile(c: Config) -> str:\n    dns_line = f"dns={c.static_dns.replace(\' \', \';\')};" if c.static_dns else ""\n    return f"""\\\n[connection]\nid={c.nm_connection}\ntype=ethernet\ninterface-name={c.static_iface}\nautoconnect=true\nautoconnect-priority={c.nm_priority}\n\n[ipv4]\nmethod=manual\naddress1={c.static_ip},{c.static_gateway}\n{dns_line}\n\n[ipv6]\nmethod=auto\n\n"""  # bash printf adds a second newline\n\n\n# ---- reboot notice ---------------------------------------------------------------------------------\n\ndef reboot_check_bin(c: Config) -> str:\n    return render("""\\\n#!/bin/bash\nset -u\ndnf needs-restarting -r > /dev/null 2>&1\nrc=$?\nif [ "${rc}" -eq 1 ]; then\n  if [ ! -e "@@notice@@" ]; then\n    mkdir -p "$(dirname "@@notice@@")"\n    printf \'%s\\\\n\' \'  - Reboot required: updates changed the kernel or core libraries. Run "sudo reboot" when convenient.\' > "@@notice@@"\n    chmod 0644 "@@notice@@"\n    logger -t @@midfix@@-reboot-check -p authpriv.warning "reboot required to finish applying updates"\n  fi\nelif [ "${rc}" -eq 0 ]; then\n  rm -f "@@notice@@"\nfi\nexit 0\n""", notice=c.reboot_notice_file, midfix=MIDFIX)\n\n\ndef reboot_check_service(c: Config) -> str:\n    return f"""\\\n[Unit]\nDescription=Check whether a reboot is required\n\n[Service]\nType=oneshot\nExecStart={c.reboot_check_bin}\n"""\n\n\ndef reboot_dnf_dropin(c: Config) -> str:\n    return f"[Service]\\nExecStartPost=-{c.reboot_check_bin}\\n"\n\n\n# ---- AIDE ------------------------------------------------------------------------------------------\n')
